  \point["{$(1,0)$}" below] at (1,0);
  \point["{$(2,0)$}" anchor=-130] at (2,0);
  \draw[thick, seq-red] (-2/3,7) --
    node[sloped,above=1pt] {$y=-3x+5$} (7/3,-2);
