  \point["{$(1,0)$}" below] at (1,0);
  \point["{$(2,0)$}" anchor=-130] at (2,0);
  \draw[decorate, seq-blue, thick, decoration={mirror}]
    (0,5) -- node[right=2mm] {$-1$} (0,6);
  \draw[decorate, seq-blue, thick]
    (1,0) -- node[left=2mm,yshift=1.5pt] {$2$} (1,2);
  \draw[decorate, seq-blue, thick]
